using System.IO.Compression;
using System.Text;
using System.Text.Json;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
public static class InfrastructureTests
{
 public static IEnumerable<(string,Action)> Cases(){
  yield return("elevated decks preserve river/road terrain and native underpass clearance",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});p=LinearFeatureEditor.Put(p,new(){Id="river",Kind="river",Width=12,Points=[new(100,30),new(100,160)]});p=LinearFeatureEditor.Put(p,new(){Id="road",Width=6,Points=[new(140,30),new(140,160)]});var before=JsonSerializer.Serialize(p);var terrain=p.Terrain.ToArray();var next=LinearFeatureEditor.Put(p,new(){Id="deck",Kind="bridge",Level=2,GuardRails=true,SupportSpacing=12,Width=6,Points=[new(50,80),new(180,80)]});Check(JsonSerializer.Serialize(p)==before&&next.Terrain.SequenceEqual(terrain)&&next.LinearFeatures[^1].Underlay.Count==0,"Elevated stroke repainted terrain or mutated input");var scene=NativeScene.Cell(next,90,72,70,16);Check(scene.Sprites.Any(s=>s.X==100&&s.Y==80&&s.Z==0&&s.Tile=="blends_natural_02_0")&&scene.Sprites.Any(s=>s.X==100&&s.Y==80&&s.Z==2&&s.Tile==InfrastructureGeometry.DeckTile),"Native river under deck was lost");Check(!scene.Sprites.Any(s=>s.X==140&&s.Y==80&&s.Z is 0 or 1&&s.Tile.StartsWith("walls_")),"Pier blocks crossing road");Check(LinearFeatureEditor.Remove(next,"deck").Terrain.SequenceEqual(terrain),"Deck removal destroyed underlay");
  });
  yield return("native stair runs have clear shafts and exact streamed geometry across positive/negative floors",()=>{
   foreach(var z in new[]{2,-2}){var p=MapGenerator.Generate(new(){Kind="blank"});p=LinearFeatureEditor.Put(p,new(){Id="stairs",Kind="bridge",Level=z,Access="stairs",Width=4,Points=[new(50,100),new(100,100)]});var geometry=InfrastructureGeometry.Build(p);Check(geometry.Tiles.Count(t=>t.Id.StartsWith("carpentry_02_9"))==6,"Wrong native stair piece count");var scene=NativeScene.Cell(p,40,88,72,24);foreach(var hole in geometry.Holes)Check(!scene.Sprites.Any(t=>t.X==hole.X&&t.Y==hole.Y&&t.Z==hole.Z),"Native stair shaft contains a blocking floor");var view=NativeViewportScene.FromProject(p).Read(32,80,96,1,z);Check(view.Sprites.Any(s=>s.Z==z&&s.Tile==InfrastructureGeometry.DeckTile),"Streamed viewport omitted deck");var original=MapGenerator.Generate(new(){Kind="blank"});Check(LinearFeatureEditor.Remove(p,"stairs").Terrain.SequenceEqual(original.Terrain),"Native stair shaft changed the terrain layer");}
  });
  yield return("infrastructure validates extremes collisions water access and atomic failed templates",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});foreach(var z in new[]{-32,31}){var next=LinearFeatureEditor.Put(p,new(){Kind="bridge",Level=z,Points=[new(30,40),new(60,40)]});ProjectValidator.Validate(next);Check(NativeScene.Cell(next,20,30,48,24,z).Sprites.Any(s=>s.Z==z),"Signed endpoint deck lost");}foreach(var z in new[]{-33,32})Reject(()=>LinearFeatureEditor.Put(p,new(){Level=z,Points=[new(30,40),new(60,40)]}));p.Buildings.Add(new(){X=50,Y=50,Width=8,Height=8});Reject(()=>LinearFeatureEditor.Put(p,new(){Level=1,Points=[new(30,52),new(70,52)]}));var before=JsonSerializer.Serialize(p);Reject(()=>JunctionTemplates.Apply(p,new(){X=20,Y=2}));Check(JsonSerializer.Serialize(p)==before,"Rejected template mutated project");var water=MapGenerator.Generate(new(){Kind="blank"});water.Terrain[84*256+50]=Terrain.Water;Reject(()=>LinearFeatureEditor.Put(water,new(){Kind="bridge",Level=1,Access="stairs",Points=[new(50,80),new(90,80)]}));
  });
  yield return("junction groups preview atomically and removal preserves independent edits",()=>{
   foreach(var kind in JunctionTemplates.Names){var p=MapGenerator.Generate(new(){Kind="blank"});var before=JsonSerializer.Serialize(p);var next=JunctionTemplates.Apply(p,new(){Kind=kind,GroupId="junction",X=100,Y=100,Span=48});Check(JsonSerializer.Serialize(p)==before&&next.LinearFeatures.All(f=>f.GroupId=="junction"),"Template preview mutated input or lost ownership");ProjectValidator.Validate(next);next.Terrain[100*256+80]=Terrain.Sand;TerrainEditMask.Mark(next,100*256+80);var removed=LinearFeatureEditor.RemoveGroup(next,"junction");Check(removed.LinearFeatures.Count==0&&removed.Terrain[100*256+80]==Terrain.Sand,"Group deletion lost independent terrain edit");}
  });
  yield return("native lotpack readback keeps deck and underlay at both sides of a cell seam",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank",Size=512});p=LinearFeatureEditor.Put(p,new(){Id="water",Kind="river",Width=20,Points=[new(256,40),new(256,200)]});p=LinearFeatureEditor.Put(p,new(){Id="seam",Kind="bridge",Level=3,Width=4,Points=[new(230,100),new(280,100)]});using var zip=new ZipArchive(new MemoryStream(NativeMapExporter.Export(p)));foreach(var x in new[]{255,256}){Check(ReadSquare(zip,p,x,100,3).Contains(InfrastructureGeometry.DeckTile),"Native seam lost deck floor");Check(ReadSquare(zip,p,x,100,0).Contains("blends_natural_02_0"),"Native seam lost underlying river");}
  });
 }
 static List<string> ReadSquare(ZipArchive zip,MapProject p,int x,int y,int z){var cx=x/256;var cy=y/256;using var h=new BinaryReader(zip.Entries.Single(e=>e.FullName.EndsWith($"/{p.WorldX+cx}_{p.WorldY+cy}.lotheader")).Open());Check(new string(h.ReadChars(4))=="LOTH"&&h.ReadInt32()==1,"Native header mismatch");var tiles=Enumerable.Range(0,h.ReadInt32()).Select(_=>Line(h)).ToArray();Check(h.ReadInt32()==8&&h.ReadInt32()==8,"Native dimensions mismatch");var min=h.ReadInt32();var max=h.ReadInt32();Check(z>=min&&z<=max,"Missing exported level");using var stream=new MemoryStream();zip.Entries.Single(e=>e.FullName.EndsWith($"/world_{p.WorldX+cx}_{p.WorldY+cy}.lotpack")).Open().CopyTo(stream);stream.Position=0;using var r=new BinaryReader(stream);Check(new string(r.ReadChars(4))=="LOTP"&&r.ReadInt32()==1&&r.ReadInt32()==1024,"Native pack mismatch");var offsets=Enumerable.Range(0,1024).Select(_=>r.ReadInt64()).ToArray();stream.Position=offsets[(x%256/8)*32+y%256/8];var target=(z-min)*64+(x%8)*8+y%8;var index=0;while(index<=target){var count=r.ReadInt32();if(count==-1){index+=r.ReadInt32();if(index>target)return [];continue;}r.ReadInt32();var result=Enumerable.Range(1,count-1).Select(_=>tiles[r.ReadInt32()]).ToList();if(index==target)return result;index++;}return [];}
 static string Line(BinaryReader r){var b=new List<byte>();byte value;while((value=r.ReadByte())!=10)b.Add(value);return Encoding.ASCII.GetString(b.ToArray());}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Expected infrastructure validation failure");}
}
